fn check_diagnostic_authority(value: &str) -> Result<(), &'static str> { let _ = value; require(value == "diagnostic_only") }
fn check_inspection_report(value: &InspectionReport) -> Result<(), &'static str> { let _ = value; check_version(&value.schema_version)?; check_diagnostic_kind(&value.kind)?; check_diagnostic_authority(&value.authority)?; check_identity(&value.identity)?; check_column(&value.column)?; check_commit(&value.implementation_commit)?; check_product_key(&value.product)?; check_inspection_outcome(&value.outcome)?; check_requirements(&value.unchecked)?; Ok(()) }
fn cause_family(code: &Code) -> Family { match code { Code::FeatureUnavailable => Family::Configuration, Code::RetainedDisabled => Family::Configuration, Code::InvalidOptions => Family::Configuration, Code::CapabilityMissing => Family::Configuration, Code::SourceInvalid => Family::Source, Code::SourceMissing => Family::Source, Code::SourceMismatch => Family::Source, Code::SourceStale => Family::Source, Code::EnumerationFailed => Family::Source, Code::OwnerMismatch => Family::Ownership, Code::OwnerRetired => Family::Ownership, Code::ReceiptInvalid => Family::Ownership, Code::OperationUnsupported => Family::Geometry, Code::GeometryInvalid => Family::Geometry, Code::OpeningInvalid => Family::Geometry, Code::LayerCutFailed => Family::Geometry, Code::InterfaceUnproven => Family::Geometry, Code::AppearanceInvalid => Family::Appearance, Code::TextureUnavailable => Family::Appearance, Code::PaletteInvalid => Family::Appearance, Code::NormalUnproven => Family::Appearance, Code::IdentityUnproven => Family::Appearance, Code::RemovalPolicyUnproven => Family::Publication, Code::PublicationFailed => Family::Publication, Code::ResourceExhausted => Family::Resource, Code::DeadlineExceeded => Family::Resource, Code::RuntimeFailed => Family::Runtime, Code::WorkerRetired => Family::Runtime, Code::DeviceLost => Family::Runtime, Code::Cancelled => Family::Runtime, Code::ConsumerUnsupported => Family::Consumer, Code::MixedEngineExportUnsupported => Family::Consumer, Code::ExportFailed => Family::Consumer, } }

